from matplotlib import font_manager
cjk = set()
for f in font_manager.fontManager.ttflist:
    if any(k in f.name for k in ["CJK", "Noto Sans SC", "WenQuanYi", "Hei", "Song", "Kai", "AR PL", "Droid Sans Fallback"]):
        cjk.add(f.name)
print("CJK fonts found:", sorted(cjk) if cjk else "NONE")
